CREATE TABLE dbo.T (Id int NOT NULL CONSTRAINT PK_T PRIMARY KEY, A int NULL, B int NULL, C varchar(20) NULL)
GO
CREATE INDEX IX_A ON dbo.T (A, B)
GO
CREATE INDEX IX_C ON dbo.T (C) INCLUDE (A) WHERE C IS NOT NULL
GO
CREATE UNIQUE INDEX UX_B ON dbo.T (B) WHERE B IS NOT NULL
GO
CREATE INDEX IX_New ON dbo.T (B DESC)
